-- EPIC-06/US-02 extension: Store Price Rule change history (tenant-scoped audit log).
-- Apply: supabase db query --file supabase/migrations/_drafts/04_catalog_store_price_rule_change_history.sql
-- Depends on: store_price_rules table; includes fix from 01_catalog_store_price_rule_fix_ambiguous_tenant.sql

create table if not exists catalog.store_price_rule_change_history (
  id uuid primary key default gen_random_uuid(),
  tenant_id uuid not null,
  store_price_rule_id uuid not null
    references catalog.store_price_rules (id) on delete cascade,
  action text not null default 'set_store_price_rule',
  payload jsonb not null default '{}'::jsonb,
  actor_id uuid not null,
  created_at timestamptz not null default now()
);

create index if not exists idx_store_price_rule_change_history_tenant_created
  on catalog.store_price_rule_change_history (tenant_id, created_at desc);

create or replace function catalog.set_store_price_rule(
  p_tenant_id uuid,
  p_name text,
  p_list_markup_ratio numeric,
  p_floor_markup_ratio numeric,
  p_status text default 'active'
)
returns table (
  id uuid,
  tenant_id uuid,
  name text,
  status text,
  calculation_type text,
  list_markup_ratio numeric,
  floor_markup_ratio numeric,
  updated_at timestamptz
)
language plpgsql
security definer
set search_path = catalog, iam, pg_temp
as $$
#variable_conflict use_column
declare
  v_rule_id uuid;
  v_old catalog.store_price_rules%rowtype;
  v_summary text;
  v_should_log boolean := false;
  v_had_old boolean;
begin
  if auth.uid() is null then
    raise exception 'not authenticated';
  end if;

  if not iam.has_permission(p_tenant_id, 'catalog.pricing.manage_store_rule') then
    raise exception 'permission denied: catalog.pricing.manage_store_rule';
  end if;

  if p_name is null or btrim(p_name) = '' then
    raise exception 'validation_exception: rule name is required';
  end if;

  if p_list_markup_ratio is null or p_list_markup_ratio < 0
     or p_floor_markup_ratio is null or p_floor_markup_ratio < 0 then
    raise exception 'validation_exception: markup ratios must be non-negative';
  end if;

  if p_status not in ('active', 'inactive') then
    raise exception 'validation_exception: invalid rule status';
  end if;

  perform 1 from catalog._compute_suggested_prices(100, p_list_markup_ratio, p_floor_markup_ratio);

  select *
  into v_old
  from catalog.store_price_rules r
  where r.tenant_id = p_tenant_id;

  v_had_old := found;

  insert into catalog.store_price_rules (
    tenant_id,
    name,
    calculation_type,
    list_markup_ratio,
    floor_markup_ratio,
    status,
    updated_at
  )
  values (
    p_tenant_id,
    btrim(p_name),
    'markup',
    p_list_markup_ratio,
    p_floor_markup_ratio,
    p_status,
    now()
  )
  on conflict on constraint store_price_rules_tenant_id_key do update set
    name = excluded.name,
    list_markup_ratio = excluded.list_markup_ratio,
    floor_markup_ratio = excluded.floor_markup_ratio,
    status = excluded.status,
    updated_at = now()
  returning store_price_rules.id into v_rule_id;

  if not v_had_old then
    v_should_log := true;
    v_summary := 'Tạo khung giá cửa hàng';
  elsif v_old.name is distinct from btrim(p_name)
     or v_old.list_markup_ratio is distinct from p_list_markup_ratio
     or v_old.floor_markup_ratio is distinct from p_floor_markup_ratio
     or v_old.status is distinct from p_status then
    v_should_log := true;
    v_summary := 'Cập nhật khung giá cửa hàng';
  end if;

  if v_should_log then
    insert into catalog.store_price_rule_change_history (
      tenant_id,
      store_price_rule_id,
      action,
      payload,
      actor_id
    )
    values (
      p_tenant_id,
      v_rule_id,
      'set_store_price_rule',
      jsonb_build_object(
        'summary', v_summary,
        'previous_name', v_old.name,
        'new_name', btrim(p_name),
        'previous_list_markup_ratio', v_old.list_markup_ratio,
        'new_list_markup_ratio', p_list_markup_ratio,
        'previous_floor_markup_ratio', v_old.floor_markup_ratio,
        'new_floor_markup_ratio', p_floor_markup_ratio,
        'previous_status', v_old.status,
        'new_status', p_status
      ),
      auth.uid()
    );
  end if;

  return query
  select
    r.id,
    r.tenant_id,
    r.name,
    r.status,
    r.calculation_type,
    r.list_markup_ratio,
    r.floor_markup_ratio,
    r.updated_at
  from catalog.store_price_rules r
  where r.id = v_rule_id;
end;
$$;

create or replace function catalog.get_store_price_rule_change_history(
  p_tenant_id uuid,
  p_limit int default 50,
  p_offset int default 0
)
returns jsonb
language plpgsql
security definer
set search_path = catalog, iam, pg_temp
as $$
declare
  v_limit int;
  v_offset int;
  v_total_count int;
  v_items jsonb;
begin
  if auth.uid() is null then
    raise exception 'not authenticated';
  end if;

  if not iam.has_permission(p_tenant_id, 'catalog.pricing.manage_store_rule') then
    raise exception 'permission denied: catalog.pricing.manage_store_rule';
  end if;

  v_limit := greatest(coalesce(p_limit, 50), 1);
  v_offset := greatest(coalesce(p_offset, 0), 0);

  if v_limit > 100 then
    raise exception 'validation_exception: Limit must be between 1 and 100.';
  end if;

  select count(*)::int
  into v_total_count
  from catalog.store_price_rule_change_history h
  where h.tenant_id = p_tenant_id;

  select coalesce(jsonb_agg(row_to_json(entry.*) order by entry.occurred_at desc), '[]'::jsonb)
  into v_items
  from (
    select
      h.id,
      h.created_at as occurred_at,
      left(h.actor_id::text, 8) as actor_display_name,
      coalesce(h.payload ->> 'summary', h.action) as summary,
      (h.payload ->> 'previous_list_markup_ratio')::numeric as list_markup_before,
      (h.payload ->> 'new_list_markup_ratio')::numeric as list_markup_after,
      (h.payload ->> 'previous_floor_markup_ratio')::numeric as floor_markup_before,
      (h.payload ->> 'new_floor_markup_ratio')::numeric as floor_markup_after,
      row_number() over (order by h.created_at desc) = 1 as is_current
    from catalog.store_price_rule_change_history h
    where h.tenant_id = p_tenant_id
    order by h.created_at desc
    limit v_limit
    offset v_offset
  ) entry;

  return jsonb_build_object(
    'items', coalesce(v_items, '[]'::jsonb),
    'total_count', coalesce(v_total_count, 0)
  );
end;
$$;

